        self.assertEqual(
            verify_bundle(bundle, self.trust, now=NOW),
            {"ok": False, "error": ERR_INTEGRITY},
        )

    def test_post_signing_tamper(self) -> None:
        bundle = self.bundle()
        bundle["expires_at"] = FUTURE + 1  # unsigned content changed
        self.assertEqual(
