    def test_duplicate_tx_id_across_blocks(self) -> None:
        # The same transaction packed in a second block violates uniqueness.
        block2 = Block.create(
            2, self.block1.block_hash, [self.tx2, self.tx]
        ) if False else None
        other = Transaction(
            self.alice_pub, BOB, 200,
            self.alice_key.sign(
                crypto.canonical_message(self.alice_pub, BOB, 200)
